		xGeometry.translate(size / 2, 0, 0);
		geometries.push(xGeometry);
		const yGeometry = new THREE.BoxGeometry(thickness, size, thickness);
		yGeometry.translate(0, size / 2, 0);
		geometries.push(yGeometry);
		const zGeometry = new THREE.BoxGeometry(thickness, thickness, size);
		zGeometry.translate(0, 0, size / 2);
		geometries.push(zGeometry);
		const combinedGeometry = mergeGeometries(geometries);
		const materials = [
			new THREE.MeshPhongMaterial({ color: colorModes[colorMode].x }),
			new THREE.MeshPhongMaterial({ color: colorModes[colorMode].y }),
			new THREE.MeshPhongMaterial({ color: colorModes[colorMode].z })
		];
